#define R iResolution.xy
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)
#define Main void mainImage(out vec4 Q, in vec2 U)
#define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))
vec4 hash(vec4 p4)
{
    p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}

Main {
     U = 2.*(U-.5*R)/R.y;
     Q = vec4(0);
     Q = sin(20.*length(U))+vec4(0);
     Q += sin(30.*length(U-.5));
     Q += sin(20.*length(U-vec2(-.3,-.4)));
     Q += .01*sin(200.*length(U-vec2(-.3,.4)));
}

Main {
    vec4 n = A(U+vec2(0,1));
    vec4 e = A(U+vec2(1,0));
    vec4 s = A(U-vec2(0,1));
    vec4 w = A(U-vec2(1,0));
    Q.xyz = normalize(vec3(e.x-w.x,n.x-s.x,1));
    Q.xyz = 5.*refract(Q.xyz,vec3(0,0,1),.5);
}

Main {
    Q = .99*A(U);
    vec4 h = hash(vec4(iFrame,iTime,U));
    for (float x = -4.; x<=4.;x++)
    for (float y = -4.; y<=4.;y++){
        vec2 v = 20.*(.5*(h.xy*2.-1.)+vec2(x,y));
        vec4 b = B(U+v);
        Q.z += .3*exp(-1.*length(100.*b.xy-v));
        Q.y += .3*exp(-1.*length(102.*b.xy-v));
        Q.x += .3*exp(-1.*length(105.*b.xy-v));
    }
}
